const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'../../../..');
const profile=path.resolve(root,'..');
const simulator=path.join(profile,'showdown');
const {createRequire}=require('node:module');
const requireSimulator=createRequire(path.join(simulator,'index.js'));
const {Battle}=requireSimulator('./sim/battle');
const {BattleStream}=requireSimulator('./sim/battle-stream');
const fields={};
for(const filename of fs.readdirSync(path.join(root,'datapack/data/rejuvenation/rejuvenation/fields'))){const f=JSON.parse(fs.readFileSync(path.join(root,'datapack/data/rejuvenation/rejuvenation/fields',filename)));fields[f.id]=f;}
const mappings=JSON.parse(fs.readFileSync(path.join(root,'datapack/data/rejuvenation/rejuvenation/mappings/modpack.json'))).rules;
const sandbox={require:requireSimulator,REJUVENATION_SHOWDOWN_ROOT:'./',console};
vm.createContext(sandbox);vm.runInContext(fs.readFileSync(path.join(root,'mod/src/main/resources/rejuvenation-engine.js'),'utf8'),sandbox);
const items=JSON.parse(fs.readFileSync(path.join(root,'datapack/data/rejuvenation/rejuvenation/items/seeds.json'))).items;
const abilities=JSON.parse(fs.readFileSync(path.join(root,'datapack/data/rejuvenation/rejuvenation/abilities/source.json'))).abilities;
const trainers={};for(const filename of fs.readdirSync(path.join(root,'datapack/data/rejuvenation/rejuvenation/trainers')))Object.assign(trainers,JSON.parse(fs.readFileSync(path.join(root,'datapack/data/rejuvenation/rejuvenation/trainers',filename))).trainers);
const E=sandbox.RejuvenationEngine;const catalog={fields,mappings,items,abilities,trainers,default:'rejuvenation:indoor'};E.load(JSON.stringify(catalog));
let count=0;const passedTests=[],failedTests=[];
function test(name,fn){try{fn();console.log('PASS '+name);passedTests.push(name);count++;}catch(e){failedTests.push(name);console.error('FAIL '+name,e);process.exitCode=1;}}
const fid=s=>'rejuvenation:'+s;
function battle(field='forest',a={},t={}){
 const b=new Battle({formatid:'gen9customgame',seed:[1,2,3,4]});
 E.attach(b,fid(field));
 function set(v,uuid){v.uuid=uuid;v.movesInfo=v.moves.map(()=>({pp:20,maxPp:20}));return v;}
 b.setPlayer('p1',{name:'A',team:[set({species:'Mew',ability:'Synchronize',moves:['psychic','surf','growth','strength'],...a},'00000000-0000-0000-0000-000000000001')]});
 b.setPlayer('p2',{name:'B',team:[set({species:'Mew',ability:'Synchronize',moves:['splash'],...t},'00000000-0000-0000-0000-000000000002')]});
 b.choose('p1','team 1');b.choose('p2','team 1');
 return b;
}
function pokemon(b){return [b.sides[0].active[0],b.sides[1].active[0]];}
function move(b,id){return b.dex.getActiveMove(id);}
test('all 57 definitions parse and are attachable',()=>{assert.equal(Object.keys(fields).length,57);for(const f of Object.values(fields)){const b=new Battle({formatid:'gen9customgame'});E.attach(b,f.id);assert.equal(E.current(b).id,f.id);b.destroy();}});
test('every Kanto league trainer starts on a shipped non-Indoor field chosen by the engine scores',()=>{
 const scores=JSON.parse(fs.readFileSync(path.join(root,'research/trainer-field-scores.json'))).trainers;
 assert.equal(Object.keys(trainers).length,13);
 for(const [id,row]of Object.entries(trainers)){assert(fields[row.field] && row.field!=='rejuvenation:indoor',id);assert.equal(row.field,scores[id].best,id);
  for(const [field,s]of Object.entries(scores[id].scores))if(field!=='rejuvenation:indoor')assert(s.winShare<row.winShare || (s.winShare===row.winShare && s.margin<=scores[id].scores[row.field].margin),id+' '+field);}
 for(const bad of [{kanto_brock:{field:'rejuvenation:indoor'}},{kanto_brock:{field:'rejuvenation:nowhere'}},{'Kanto Brock':{field:'rejuvenation:cave'}},{kanto_brock:{field:'rejuvenation:cave',winShare:2}},{kanto_brock:{field:'rejuvenation:cave',team:[]}}])
  assert.throws(()=>E.load(JSON.stringify({...catalog,trainers:bad})),JSON.stringify(bad));
 E.load(JSON.stringify(catalog));});
test('unknown conditions and invalid transitions reject catalog',()=>{const c=JSON.parse(JSON.stringify(catalog));c.fields[fid('forest')].rules.push({event:'residual',condition:{nonsense:true},actions:[]});assert.throws(()=>E.load(JSON.stringify(c)));});
test('field initialization and original message',()=>{const b=battle();assert.equal(E.current(b).id,fid('forest'));assert(b.log.some(s=>s.includes('The field is abound with trees.')));b.destroy();});
test('every discovered biome resolves intentionally',()=>{const rows=JSON.parse(fs.readFileSync(path.join(root,'research/biome-mapping.json')));for(const row of rows)assert.equal(E.resolve({biome:row.biome,dimension:'minecraft:overworld',tags:[],submerged:false,y:64,skyVisible:true}),row.field);});
test('unknown tag, dimension and no-field fallback',()=>{assert.equal(E.resolve({biome:'future:trees',tags:['minecraft:is_forest']}),fid('forest'));assert.equal(E.resolve({biome:'future:lava',dimension:'minecraft:the_nether'}),fid('volcanic'));assert.equal(E.resolve({biome:'future:blank',y:64}),fid('indoor'));});
test('underwater environment overrides surface biome',()=>assert.equal(E.resolve({biome:'minecraft:ocean',dimension:'minecraft:overworld',submerged:true}),fid('underwater')));
test('representative Forest type power',()=>{const b=battle(),[u,t]=pokemon(b);const m=move(b,'energyball');const result=b.runEvent('BasePower',u,t,m,90);assert.equal(result,135);b.destroy();});
test('accuracy replacement',()=>{const b=battle('grassy_terrain'),[u,t]=pokemon(b),m=move(b,'grasswhistle');b.runEvent('ModifyMove',u,t,m,m);assert.equal(m.accuracy,80);b.destroy();});
test('actual move type changes',()=>{const b=battle('beach'),[u,t]=pokemon(b),m=move(b,'strength');b.runEvent('ModifyMove',u,t,m,m);assert.equal(m.type,'Fighting');b.destroy();});
test('additional type is not replacement type',()=>{const b=battle('electric_terrain'),[u,t]=pokemon(b),m=move(b,'surf');b.runEvent('ModifyMove',u,t,m,m);assert.equal(m.type,'Water');assert.equal(m.rejuvenationTypes[0],'Electric');b.destroy();});
test('priority changes',()=>{const b=battle('dimensional'),[u,t]=pokemon(b),m=move(b,'quash');assert.equal(b.runEvent('ModifyPriority',u,null,m,m.priority),m.priority+1);b.destroy();});
test('ability switch-in',()=>{const b=battle('electric_terrain',{ability:'Lightning Rod'}),[u]=pokemon(b);assert.equal(u.boosts.spa,1);b.destroy();});
test('item switch-in consumption',()=>{const b=battle('electric_terrain',{item:'Cell Battery'}),[u]=pokemon(b);assert.equal(u.boosts.atk,1);assert.equal(u.item,'');b.destroy();});
test('field transition counters and exact messages',()=>{const b=battle('forest'),[u,t]=pokemon(b);for(let i=0;i<3;i++)b.runEvent('AfterMove',u,t,move(b,'surf'));assert.equal(E.current(b).id,fid('swamp'));assert(b.log.some(s=>s.includes('waterlogged')));b.destroy();});
test('temporary duration and chained replacement restoration',()=>{const b=battle('forest');E.change(b,fid('cave'),{duration:2,force:true});E.change(b,fid('rocky'));b.residualEvent('Residual');assert.equal(E.current(b).id,fid('rocky'));b.residualEvent('Residual');assert.equal(E.current(b).id,fid('forest'));b.destroy();});
test('temporary overlay preserves hard field',()=>{const b=battle('forest');E.change(b,fid('electric_terrain'),{duration:2});assert.equal(E.current(b).id,fid('forest'));assert.equal(b.rejuvenation.overlay.id,fid('electric_terrain'));b.residualEvent('Residual');b.residualEvent('Residual');assert.equal(b.rejuvenation.overlay,null);b.destroy();});
test('end-turn recovery',()=>{const b=battle('forest',{ability:'Sap Sipper'}),[u]=pokemon(b);u.hp=Math.floor(u.maxhp/2);const hp=u.hp;b.residualEvent('Residual');assert.equal(u.hp,hp+Math.floor(u.maxhp/16));assert(b.log.some(s=>s.includes('drank tree sap')));b.destroy();});
test('field destruction restores previous layer',()=>{const b=battle('forest');E.change(b,fid('cave'),{push:true});E.destroy(b,'The cave was destroyed!');assert.equal(E.current(b).id,fid('forest'));assert(b.log.some(s=>s.includes('The cave was destroyed!')));b.destroy();});
test('simultaneous battle isolation and cleanup',()=>{const a=battle('forest'),b=battle('desert');E.change(a,fid('rocky'));assert.equal(E.current(b).id,fid('desert'));a.destroy();assert.equal(a.rejuvenation,undefined);b.destroy();});
test('vanilla battle remains without custom state',()=>{const b=new Battle({formatid:'gen9customgame'});assert.equal(b.rejuvenation,undefined);b.destroy();});
test('stream initializes field before first switch',()=>{const s=new BattleStream();s._writeLine('start',JSON.stringify({formatid:'gen9customgame',rejuvenationField:fid('forest')}));assert.equal(s.battle.rejuvenation.id,fid('forest'));s.battle.destroy();});
test('defensive type boost',()=>{const b=battle('desert',{species:'Sandshrew'}),[u,t]=pokemon(b),m=move(b,'psychic');assert.equal(b.runEvent('ModifySpD',u,t,m,100),150);b.destroy();});
test('Mega Sol overrides hail for field defense',()=>{const b=battle('icy',{species:'Glaceon'},{ability:'Mega Sol'}),[u,t]=pokemon(b);b.field.setWeather('hail',u);assert.equal(b.runEvent('ModifyDef',u,t,move(b,'tackle'),100),100);t.setAbility('synchronize');assert.equal(b.runEvent('ModifyDef',u,t,move(b,'tackle'),100),150);b.destroy();});
test('Deux Finalis defense uses attacker-relative weather',()=>{const b=battle('deux_finalis',{species:'Snorlax'},{ability:'Mega Sol'}),[u,t]=pokemon(b);b.field.setWeather('raindance',u);assert.equal(b.runEvent('ModifyDef',u,t,move(b,'tackle'),100),130);t.setAbility('synchronize');assert.equal(b.runEvent('ModifyDef',u,t,move(b,'tackle'),100),100);b.destroy();});
test('Haunted permits consecutive Destiny Bond while native failure remains elsewhere',()=>{for(const field of ['haunted','indoor']){const b=battle(field,{moves:['destinybond']}),[u]=pokemon(b);for(let n=0;n<2;n++){b.choose('p1','move 1');b.choose('p2','move 1');}assert.equal(!!u.volatiles.destinybond,field==='haunted');assert.equal(b.log.some(s=>s.startsWith('|-fail|')),field==='indoor');b.destroy();}});
test('Glitch Sleep Talk calls Rest and restarts sleep without curing Nightmare',()=>{const b=battle('glitch',{moves:['sleeptalk','rest']}),[u]=pokemon(b);u.hp=Math.floor(u.maxhp/2);u.setStatus('slp');u.statusState.time=5;u.addVolatile('nightmare',u,move(b,'nightmare'));b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.status,'slp');assert.equal(u.statusState.time,3);assert(u.volatiles.nightmare);assert.equal(u.hp,u.maxhp-Math.floor(u.maxhp/4));assert(b.log.some(s=>s.includes('slept and restored its HP!')));b.destroy();});
test('Sleep Talk Rest retains native failure outside Glitch',()=>{const b=battle('indoor',{moves:['sleeptalk','rest']}),[u]=pokemon(b);u.hp=Math.floor(u.maxhp/2);const before=u.hp;u.setStatus('slp');u.statusState.time=5;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.hp,before);assert.equal(u.statusState.time,4);b.destroy();});
test('Glitch Rest refresh respects new sleep restrictions and restores old state',()=>{const b=battle('glitch',{moves:['sleeptalk','rest']}),[u]=pokemon(b);u.hp=Math.floor(u.maxhp/2);const before=u.hp;u.setStatus('slp');u.statusState.time=5;E.change(b,fid('electric_terrain'),{duration:3});b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.hp,before);assert.equal(u.status,'slp');assert.equal(u.statusState.time,4);b.destroy();});
test('underwater speed penalty and Water exemption',()=>{const a=battle('underwater'),[u]=pokemon(a);assert.equal(a.runEvent('ModifySpe',u,null,null,100),50);a.destroy();const b=battle('underwater',{species:'Squirtle'}),[v]=pokemon(b);assert.equal(b.runEvent('ModifySpe',v,null,null,100),100);b.destroy();});
test('status move changes are used during a complete turn',()=>{const b=battle('forest',{moves:['growth']}),[u]=pokemon(b);b.choose('p1','move growth');b.choose('p2','move splash');assert.equal(u.boosts.atk,2);assert.equal(u.boosts.spa,2);b.destroy();});
test('healing move override',()=>{const b=battle('starlight'),[u,t]=pokemon(b),m=move(b,'moonlight');b.runEvent('ModifyMove',u,t,m,m);assert.equal(m.heal[0]/m.heal[1],.75);assert.equal(m.onHit,undefined);b.destroy();});
test('Seed custom held item is functional',()=>{const b=battle('electric_terrain',{item:'Elemental Seed'}),[u]=pokemon(b);assert.equal(u.item,'');assert.equal(u.boosts.spe,1);assert(u.volatiles.charge);b.destroy();});
test('source-specific Secret Power and secondary effects',()=>{const b=battle('flower_garden_5'),[u,t]=pokemon(b),m=move(b,'secretpower');b.runEvent('ModifyMove',u,t,m,m);assert.equal(m.secondaries[0].boosts.def,2);b.destroy();const a=battle('haunted'),[s,v]=pokemon(a),lick=move(a,'lick');a.runEvent('ModifyMove',s,v,lick,lick);assert.equal(lick.secondaries[0].chance,100);a.destroy();});
test('weather transition at end of turn',()=>{const b=battle('volcanic'),[u]=pokemon(b);b.field.setWeather('raindance',u);b.residualEvent('Residual');assert.equal(E.current(b).id,fid('cave'));assert(b.log.some(s=>s.includes('The rain snuffed out the flame!')));b.destroy();});
test('three snow turns progress Mountain',()=>{const b=battle('mountain'),[u]=pokemon(b);b.field.setWeather('snow',u);for(let i=0;i<3;i++)b.residualEvent('Residual');assert.equal(E.current(b).id,fid('snowy_mountain'));b.destroy();});
test('weather temporary restoration and permanence on transformation',()=>{const b=battle('dark_crystal_cavern'),[u]=pokemon(b);b.field.setWeather('sunnyday',u);b.residualEvent('Residual');assert.equal(E.current(b).id,fid('crystal_cavern'));b.field.clearWeather();b.residualEvent('Residual');assert.equal(E.current(b).id,fid('dark_crystal_cavern'));b.destroy();});
test('New World rejects weather with original text',()=>{const b=battle('new_world'),[u]=pokemon(b);b.field.setWeather('raindance',u);assert.equal(b.field.weather,'');assert(b.log.some(s=>s.includes('The weather drifted off into space...')));b.destroy();});
test('pollution is full HP loss, including Magic Guard',()=>{const b=battle('underwater',{ability:'Magic Guard'},{species:'Muk'}),[u,t]=pokemon(b);E.runActions([{op:'water_pollution'}],{b,user:u,target:t});assert.equal(u.hp,0);assert(t.hp>0);assert(b.log.some(s=>s.includes('The water was polluted!')));b.destroy();});
test('cave collapse counter, protection and exact original text',()=>{const b=battle('cave',{ability:'Sturdy'},{ability:'Bulletproof'}),[u,t]=pokemon(b);E.runActions([{op:'cave_collapse'}],{b,user:u,target:t,move:move(b,'earthquake')});assert(b.log.some(s=>s.includes('Bits of rock fell')));E.runActions([{op:'cave_collapse'}],{b,user:u,target:t,move:move(b,'earthquake')});assert.equal(u.hp,1);assert.equal(t.hp,t.maxhp);assert.equal(b.rejuvenation.counters[0],0);b.destroy();});
test('short circuit power roll locks across multiple hits',()=>{const b=battle('short_circuit'),[u,t]=pokemon(b),m=move(b,'thunderbolt');b.activeMove=m;const a=b.runEvent('BasePower',u,t,m,100),c=b.runEvent('BasePower',u,t,m,100);assert.equal(a,c);assert.equal(b.rejuvenation.roll,1);b.destroy();});
test('crystal secondary type rolls sequentially',()=>{const b=battle('crystal_cavern'),[u,t]=pokemon(b);for(const expected of ['Fire','Water','Grass','Psychic']){const m=move(b,'rockslide');b.activeMove=m;b.runEvent('ModifyMove',u,t,m,m);assert.equal(m.rejuvenationTypes[0],expected);}b.destroy();});
test('field catalog reload retains active battle snapshot',()=>{const b=battle('forest');const before=b.rejuvenation.catalog;E.load(JSON.stringify(catalog));assert.equal(b.rejuvenation.catalog,before);const a=battle('forest');assert.notEqual(a.rejuvenation.catalog,before);a.destroy();b.destroy();});
test('native terrain callback does not double custom terrain power',()=>{const b=battle('electric_terrain'),[u,t]=pokemon(b),m=move(b,'thunderbolt');const base=b.runEvent('BasePower',u,t,m,100);b.field.setTerrain('electricterrain',u);assert.equal(b.runEvent('BasePower',u,t,m,100),base);b.destroy();});
test('Deep Earth temporary expiry clears gravity',()=>{const b=battle('forest');E.change(b,fid('deep_earth'),{duration:1,force:true});assert(b.field.pseudoWeather.gravity);b.residualEvent('Residual');assert.equal(b.field.pseudoWeather.gravity,undefined);b.destroy();});
test('Mimicry changes on field change and restores base typing',()=>{const b=battle('forest',{ability:'Mimicry'}),[u]=pokemon(b);assert(u.hasType('Bug'));E.change(b,fid('desert'));assert(u.hasType('Ground'));E.destroy(b);assert(u.hasType('Psychic'));b.destroy();});
test('eruption is armed once and ends after one residual',()=>{const b=battle('volcanic_top'),[u,t]=pokemon(b);E.runActions([{op:'arm_eruption'}],{b,user:u});const hp=t.hp;b.residualEvent('Residual');assert(t.hp<hp);const damaged=t.hp;assert.equal(b.rejuvenation.eruption,false);b.residualEvent('Residual');assert.equal(t.hp,damaged);b.destroy();});
test('field-active Swift Swim avoids doubling native Rain twice',()=>{const b=battle('water_surface',{ability:'Swift Swim'}),[u]=pokemon(b);assert.equal(b.runEvent('ModifySpe',u,null,null,100),200);b.field.setWeather('raindance',u);assert.equal(b.runEvent('ModifySpe',u,null,null,100),200);b.destroy();});
test('malformed action rejects reload without changing live catalog',()=>{const b=battle('forest'),old=b.rejuvenation.catalog;const c=JSON.parse(JSON.stringify(catalog));c.fields[fid('forest')].rules[0].actions=[{op:'executeCode'}];assert.throws(()=>E.load(JSON.stringify(c)));assert.equal(b.rejuvenation.catalog,old);b.destroy();});
test('Cobblemon doubles counts a spread move once and broadcasts one field entry',()=>{
 const b=new Battle({formatid:'cobblemondoubles',seed:[1,2,3,4]});E.attach(b,fid('forest'));
 for(let side=1;side<=2;side++)b.setPlayer('p'+side,{name:'Player '+side,team:[0,1].map(n=>({species:'Blissey',ability:'Natural Cure',moves:[side===1&&n===0?'surf':'splash'],uuid:`00000000-0000-0000-0000-0000000000${side}${n}`,movesInfo:[{pp:20,maxPp:20}]}))});
 b.choose('p1','move 1, move 1');b.choose('p2','move 1, move 1');assert.equal(b.rejuvenation.counters[0],1);assert.equal(b.log.filter(s=>s.includes('The field is abound with trees.')).length,1);b.destroy();
});
test('Grassy Glide priority applies once including airborne users',()=>{for(const ability of ['Synchronize','Levitate']){const b=battle('grassy_terrain',{ability}),[u,t]=pokemon(b),m=move(b,'grassyglide');const native=b.singleEvent('ModifyPriority',m,null,u,t,m,m.priority);assert.equal(b.runEvent('ModifyPriority',u,t,m,native),1);b.destroy();}});
test('native Grassy Glide priority remains active in ordinary battles',()=>{const b=new Battle({formatid:'gen9customgame'});b.setPlayer('p1',{team:[{species:'Mew',moves:['grassyglide'],uuid:'normal-a',movesInfo:[{pp:20,maxPp:20}]}]});b.setPlayer('p2',{team:[{species:'Mew',moves:['splash'],uuid:'normal-b',movesInfo:[{pp:20,maxPp:20}]}]});b.choose('p1','team 1');b.choose('p2','team 1');const [u,t]=pokemon(b),m=move(b,'grassyglide');b.field.setTerrain('grassyterrain',u);assert.equal(b.singleEvent('ModifyPriority',m,null,u,t,m,m.priority),1);b.destroy();});
test('Inverse field reverses type immunities and preserves Levitate',()=>{const b=battle('inverse',{species:'Pidgeot'},{species:'Gengar',ability:'Levitate'}),[u,t]=pokemon(b);assert.equal(u.runImmunity('Ground'),true);assert.equal(t.runImmunity('Ground'),false);assert.equal(t.runImmunity('Normal'),true);b.destroy();});
test('Chess allocates pieces with source party order and king preference',()=>{
 const b=new Battle({formatid:'gen9customgame'});E.attach(b,fid('chess_board'));
 const species=['Mew','Kingambit','Ninjask','Alakazam','Shuckle','Blissey'];
 for(let side=1;side<=2;side++)b.setPlayer('p'+side,{team:species.map((species,i)=>({species,ability:i===1?'Supreme Overlord':'Run Away',moves:['splash'],uuid:'piece-'+side+i,movesInfo:[{pp:20,maxPp:20}]}))});
 b.choose('p1','team 1, 2, 3, 4, 5, 6');b.choose('p2','team 1, 2, 3, 4, 5, 6');
 const p=b.sides[0].pokemon;assert.deepEqual(p.map(p=>p.rejuvenationRoles[fid('chess_board')]),['pawn','king','knight','bishop','rook','queen']);
 const [u,t]=pokemon(b),m=move(b,'psychic');assert.equal(b.runEvent('ModifyPriority',p[1],t,m,0),1);
 b.activeMove=m;assert.equal(b.runEvent('Damage',u,t,m,u.hp),u.hp-1);assert.equal(b.runEvent('Damage',u,t,m,u.hp),u.hp);
 assert.equal(b.runEvent('TryHit',u,t,move(b,'fissure')),false);b.destroy();
});
test('Chess queen boost does not double Queenly Majesty',()=>{const b=battle('chess_board',{ability:'Queenly Majesty'}),[u,t]=pokemon(b),m=move(b,'watergun');b.activeMove=m;assert.equal(u.boosts.def,1);assert.equal(u.boosts.spd,1);assert.equal(b.runEvent('BasePower',u,t,m,100),150);b.destroy();});
test('all declarative type-chart overrides match their source pair',()=>{for(const f of Object.values(fields))for(const row of f.typeChart || []){
 const b=battle(f.id.split(':')[1]),[u,t]=pokemon(b);const m=move(b,row.condition.move || 'tackle');m.type=row.attackType==='*'?'Normal':row.attackType;t.setType(row.defenseType==='*'?'Normal':row.defenseType);
 if(row.condition.ability)u.setAbility(row.condition.ability.values[0]);const held=row.condition.effectiveAbility || row.condition.sideAbility;if(held)(held.who==='target'?t:u).setAbility(held.values[0]);b.activePokemon=u;b.activeMove=m;
 if(row.value==='immune')assert.equal(t.runImmunity(m.type),false,f.id);else{assert.equal(t.runImmunity(m.type),true,f.id);assert.equal(t.runEffectiveness(m),row.value,f.id);}
 b.destroy();
}});
test('raw immunity query still distinguishes Flying chart and Levitate before move override',()=>{const b=battle('cave'),[u,t]=pokemon(b),m=move(b,'earthquake');t.setType('Flying');b.activeMove=m;b.activePokemon=u;assert(t.runImmunity('Ground'));t.setAbility('levitate');assert.equal(t.runImmunity('Ground'),false);b.destroy();});
test('Glitch converts Fairy moves to the source typeless type',()=>{const b=battle('glitch'),[u,t]=pokemon(b),m=move(b,'moonblast');b.runEvent('ModifyMove',u,t,m,m);assert.equal(m.type,'???');assert.equal(m.category,'Physical');b.activeMove=m;assert(t.runImmunity(m.type));b.destroy();});
test('secondary types activate absorbing abilities once',()=>{for(const [field,ability,moveId,extra,stat] of [['crystal_cavern','Flash Fire','rockslide','Fire',null],['rainbow','Water Absorb','triattack','Water',null],['rainbow','Lightning Rod','triattack','Electric','spa'],['rainbow','Sap Sipper','triattack','Grass','atk']]){
 const b=battle(field,{}, {ability}),[u,t]=pokemon(b),m=move(b,moveId);t.hp=Math.floor(t.maxhp/2);const hp=t.hp;m.rejuvenationTypes=[extra];b.activePokemon=u;b.activeMove=m;
 assert.equal(b.runEvent('TryHit',t,u,m),null,ability);if(stat)assert.equal(t.boosts[stat],1);if(ability==='Water Absorb')assert.equal(t.hp,hp+Math.floor(t.maxhp/4));if(ability==='Flash Fire')assert(t.volatiles.flashfire);b.destroy();
}});
test('Frozen Dimension disables Flash Fire and restores it on replacement',()=>{const b=battle('frozen_dimension',{}, {ability:'Flash Fire'}),[u,t]=pokemon(b),m=move(b,'flamethrower');assert.equal(b.runEvent('TryHit',t,u,m),true);E.change(b,fid('forest'));assert.equal(b.runEvent('TryHit',t,u,m),null);b.destroy();});
test('No Retreat and Take Heart effects execute during complete turns',()=>{
 for(const [field,moveId,expected]of [['chess_board','noretreat',{atk:2,spa:2,spe:2,def:0,spd:0}],['water_surface','takeheart',{spa:2,spd:2}]]){
  const b=battle(field,{moves:[moveId],ability:'Run Away'}),[u]=pokemon(b);if(moveId==='takeheart')u.setStatus('brn');b.choose('p1','move 1');b.choose('p2','move 1');for(const [key,value]of Object.entries(expected))assert.equal(u.boosts[key],value,key);if(moveId==='takeheart')assert.equal(u.status,'');b.destroy();
 }
});
test('Clangorous Soul pays field cost and applies field boosts',()=>{const b=battle('big_top',{moves:['clangoroussoul']}),[u]=pokemon(b),before=u.hp;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.hp,before-Math.floor(u.maxhp/2));for(const key of ['atk','def','spa','spd','spe'])assert.equal(u.boosts[key],2,key);b.destroy();});
test('Aurora Veil works without weather on Crystal Cavern',()=>{const b=battle('crystal_cavern',{moves:['auroraveil']}),[u]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert(u.side.sideConditions.auroraveil);b.destroy();});
test('Magic Powder adds Psychic/Fairy typing in Fairytale',()=>{const b=battle('fairytale',{moves:['magicpowder']}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.getTypes().join('/'),'Psychic/Fairy');b.destroy();});
test('field status and confusion immunities work through native APIs',()=>{for(const [field,ability,types,status]of [['concert_3','Run Away','Normal','slp'],['sky','Early Bird','Normal','slp'],['volcanic','Run Away','Normal','frz']]){const b=battle(field,{}, {ability}),[u,t]=pokemon(b);t.setType(types);assert.equal(t.trySetStatus(status,u,move(b,'hypnosis')),false);b.destroy();}const b=battle('beach',{}, {species:'Machamp'}),[u,t]=pokemon(b);assert.equal(t.addVolatile('confusion',u,move(b,'confuseray')),false);b.destroy();});
test('Frozen Dimension removes Magma Armor freeze immunity',()=>{const b=battle('frozen_dimension',{}, {ability:'Magma Armor'}),[u,t]=pokemon(b);assert.equal(t.trySetStatus('frz',u,move(b,'icebeam')),true);b.destroy();});
test('Snowscape move uses the native snow weather identifier',()=>{const b=battle('mountain',{moves:['snowscape']}),[u]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(b.field.weather,'snow');for(let i=0;i<2;i++)b.residualEvent('Residual');assert.equal(E.current(b).id,fid('snowy_mountain'));b.destroy();});
test('absorbed healing rounds Big Root before field scaling',()=>{const b=battle('grassy_terrain',{item:'Big Root'}),[u,t]=pokemon(b);u.hp=20;const restored=b.heal(9,u,t,b.dex.conditions.get('leechseed'));assert.equal(restored,Math.round(Math.round(9*1.6)*1.3));b.destroy();});
test('Aqua Ring and Ingrain scaling avoid overlay duplication',()=>{const b=battle('forest'),[u]=pokemon(b);u.hp=20;assert.equal(b.heal(10,u,u,b.dex.conditions.get('ingrain')),20);E.change(b,fid('grassy_terrain'),{overlay:true,duration:3});assert.equal(b.heal(10,u,u,b.dex.conditions.get('ingrain')),20);E.change(b,fid('underwater'));assert.equal(b.heal(10,u,u,b.dex.conditions.get('aquaring')),20);b.destroy();});
test('poisoned water and roots replace healing with source-specific damage',()=>{for(const [field,agent,ability,loss]of [['corrosive_mist','aquaring','Magic Guard',10],['corrosive','ingrain','Magic Guard',0],['corrupted','ingrain','Run Away',10]]){const b=battle(field,{ability}),[u]=pokemon(b);u.hp=100;assert.equal(b.heal(10,u,u,b.dex.conditions.get(agent)),0);assert.equal(u.hp,100-loss);b.destroy();}});
test('Liquid Ooze and Swamp drain stat loss include full-HP healing attempts',()=>{const b=battle('wasteland',{}, {ability:'Liquid Ooze'}),[u,t]=pokemon(b);u.hp=100;assert.equal(b.heal(10,u,t,'drain'),0);assert.equal(u.hp,80);b.destroy();const a=battle('swamp'),[v,w]=pokemon(a);assert.equal(a.heal(10,v,w,'drain'),false);assert.equal(Object.values(w.boosts).reduce((n,v)=>n+v,0),-1);a.destroy();});
test('Back Alley preserves full-HP restoration and minimum one HP',()=>{const b=battle('back_alley'),[u]=pokemon(b);u.hp=1;assert.equal(b.heal(u.maxhp,u,u,move(b,'recover')),u.maxhp-1);u.hp=1;assert.equal(b.heal(1,u,u,move(b,'recover')),1);b.destroy();});
test('Amulet Coin supplies Dragon Den status immunity',()=>{const b=battle('dragons_den',{}, {item:'Amulet Coin'}),[u,t]=pokemon(b);assert.equal(t.trySetStatus('brn',u,move(b,'willowisp')),false);assert(b.log.some(s=>s.includes('The Amulet Coin prevents')));b.destroy();});
test('Glitch critical stage compares stored speed, not boosted speed',()=>{const b=battle('glitch'),[u,t]=pokemon(b),m=move(b,'tackle');u.storedStats.spe=200;t.storedStats.spe=100;u.boosts.spe=-6;assert.equal(b.runEvent('ModifyCritRatio',u,t,m,1),2);b.destroy();});
test('Chess critical modifiers preserve the unreachable lower HP branch',()=>{const b=battle('chess_board',{ability:'Merciless'}, {ability:'Gorilla Tactics'}),[u,t]=pokemon(b),m=move(b,'tackle');t.lastMove=move(b,'thrash');t.hp=Math.floor(t.maxhp*.2);assert.equal(b.runEvent('ModifyCritRatio',u,t,m,1),4);t.hp=t.maxhp;assert.equal(b.runEvent('ModifyCritRatio',u,t,m,1),3);b.destroy();});
test('field guaranteed critical hits run through the damage calculation',()=>{const b=battle('colosseum',{}, {ability:'Rattled'}),[u,t]=pokemon(b),m=move(b,'tackle');b.activePokemon=u;b.activeMove=m;b.actions.getDamage(u,t,m);assert.equal(t.getMoveHitData(m).crit,true);b.destroy();});
test('Glitch Seed and Mimicry use typeless typing',()=>{for(const a of [{item:'Synthetic Seed'},{ability:'Mimicry'}]){const b=battle('glitch',a),[u]=pokemon(b);assert.equal(u.getTypes().join('/'),'???');b.destroy();}});
test('Deep Earth weight modifiers respect native item and ability ordering',()=>{for(const [ability,item,factor]of [['Run Away','',2],['Heavy Metal','',4],['Light Metal','Float Stone',.5]]){const b=battle('deep_earth',{ability,item}),[u]=pokemon(b);assert.equal(u.getWeight(),u.weighthg*factor);b.destroy();}const b=battle('deep_earth',{item:'Telluric Seed',ability:'Heavy Metal'}),[u]=pokemon(b);assert.equal(u.getWeight(),u.weighthg*8);E.change(b,fid('forest'));assert.equal(u.getWeight(),u.weighthg*4);u.clearVolatile();assert.equal(u.getWeight(),u.weighthg*2);b.destroy();});
test('Ashen Beach Seed boosts crit stage without a duration',()=>{const b=battle('beach',{item:'Telluric Seed'}),[u,t]=pokemon(b);assert(u.volatiles.focusenergy);assert.equal(u.volatiles.focusenergy.duration,undefined);assert.equal(b.runEvent('ModifyCritRatio',u,t,move(b,'tackle'),1),4);for(let i=0;i<4;i++)b.residualEvent('Residual');assert(u.volatiles.focusenergy);b.destroy();});
test('Ashen Beach Focus Energy uses the same persistent third stage',()=>{const b=battle('beach',{moves:['focusenergy']}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(b.runEvent('ModifyCritRatio',u,t,move(b,'tackle'),1),4);b.destroy();});
test('binding seeds store native move identity and four-turn duration',()=>{for(const [field,item,source]of [['desert','Telluric Seed','sandtomb'],['volcanic','Elemental Seed','firespin']]){const b=battle(field,{item}),[u]=pokemon(b);assert.equal(u.volatiles.partiallytrapped.sourceEffect.id,source);assert.equal(u.volatiles.partiallytrapped.duration,4);b.destroy();}});
test('New World seed applies native recharge instead of an unused volatile',()=>{const b=battle('new_world',{item:'Magical Seed'}),[u]=pokemon(b);assert(u.volatiles.mustrecharge);b.choose('p1','move 1');b.choose('p2','move 1');assert(b.log.some(s=>s.includes('cant|p1a')&&s.includes('recharge')));assert(!u.volatiles.mustrecharge);b.destroy();});
test('Volcanic Top seed releases Shell Trap after a physical hit',()=>{const b=battle('volcanic_top',{item:'Telluric Seed',moves:['splash']},{moves:['tackle']}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert(b.log.some(s=>s.startsWith('|move|p1a:')&&s.includes('|Shell Trap|')));assert(t.hp<t.maxhp);assert(!u.volatiles.shelltrap);b.destroy();});
test('every defined field Seed activates and is consumed',()=>{for(const f of Object.values(fields)){if(!f.seed)continue;const b=battle(f.id.split(':')[1],{item:items[f.seed.item].name}),[u]=pokemon(b);assert.equal(u.item,'',f.originalId);b.destroy();}});
test('creation policies reject terrain with exact original messages',()=>{for(const [field,text]of [['new_world','no solid ground'],['underwater','disappeared in the water'],['frozen_dimension','remains unchanged']]){const b=battle(field,{moves:['electricterrain']}),[u]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(b.field.terrain,'');assert.equal(b.rejuvenation.overlay,null);assert(b.log.some(s=>s.includes(text)));b.destroy();}const b=battle('corrosive_mist'),[u]=pokemon(b);assert.equal(b.field.setTerrain('mistyterrain',u,move(b,'mistyterrain')),false);b.destroy();});
test('terrain moves ignore Everstone and Amplifield Rock extends them',()=>{for(const mid of ['electricterrain','mistyterrain','psychicterrain']){const a=battle('cave',{item:'Everstone',moves:[mid]});a.choose('p1','move 1');a.choose('p2','move 1');assert.equal(a.rejuvenation.overlay?.duration,4,mid);a.destroy();}const b=battle('forest',{item:'Amplifield Rock'}),[u]=pokemon(b);b.field.setTerrain('electricterrain',u,move(b,'electricterrain'));assert.equal(b.rejuvenation.overlay.duration,8);b.destroy();});
test('Deep Earth levitation exceptions precede gravity but respect roots',()=>{const b=battle('deep_earth',{ability:'Contrary',item:'Iron Ball'}),[u,t]=pokemon(b);assert.equal(u.isGrounded(),false);assert.equal(t.isGrounded(),true);assert.equal(u.runImmunity('Ground'),false);u.addVolatile('ingrain',u);assert.equal(u.isGrounded(),true);b.destroy();});
test('Deep Earth Gravity and Magnet Rise use contextual move behavior',()=>{const b=battle('deep_earth',{moves:['gravity']},{moves:['growl']}),[u,t]=pokemon(b),before=t.hp;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.hp,before-Math.floor(before/2));assert(b.field.pseudoWeather.gravity);b.destroy();const a=battle('deep_earth',{moves:['magnetrise']}),[v]=pokemon(a);a.choose('p1','move 1');a.choose('p2','move 1');assert.equal(v.boosts.spe,2);assert(!v.volatiles.magnetrise);a.destroy();});
test('fixed-damage field moves retain level scaling and original feedback',()=>{for(const [field,mid,text]of [['deep_earth','seismictoss','Slammed into the ground!'],['bewitched','nightshade','Shadowy figures came out of the woods!']]){const b=battle(field,{moves:[mid]},{moves:['growl']}),[u,t]=pokemon(b),before=t.hp;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.hp,before-Math.floor(u.level*1.5));assert(b.log.some(s=>s.includes(text)));b.destroy();}});
test('Floral Healing fully restores recipients in Grassy terrain',()=>{const b=battle('grassy_terrain',{moves:['floralhealing']}),[u,t]=pokemon(b);t.hp=1;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.hp,t.maxhp);b.destroy();});
test('Pledge memory persists across turns and creates a temporary hard field',()=>{const b=battle('indoor',{moves:['firepledge','waterpledge','grasspledge'],level:20},{moves:['growl'],level:100}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(E.current(b).id,fid('indoor'));assert(b.log.some(s=>s.includes('The Fire Pledge lingers in the air...')));b.choose('p1','move 2');b.choose('p2','move 1');assert.equal(E.current(b).id,fid('rainbow'));assert.equal(b.rejuvenation.duration,3);assert(b.log.some(s=>s.includes('The pledges combined to form a rainbow!')));assert(!u.side.sideConditions.waterpledge);for(let i=0;i<3;i++)b.residualEvent('Residual');assert.equal(E.current(b).id,fid('indoor'));b.destroy();});
test('all Pledge pairs select the source field and Amplifield duration',()=>{for(const [first,next,field]of [['firepledge','grasspledge','volcanic'],['grasspledge','waterpledge','swamp'],['waterpledge','firepledge','rainbow']]){const b=battle('indoor',{item:'Amplifield Rock',moves:[first,next],level:10},{moves:['growl'],level:100});b.choose('p1','move 1');b.choose('p2','move 1');b.choose('p1','move 2');b.choose('p2','move 1');assert.equal(E.current(b).id,fid(field));assert.equal(b.rejuvenation.duration,6);b.destroy();}});
test('Forest Grassy Terrain lasts eight turns from the move and from Grassy Surge',()=>{for(const [source,duration]of [['move',8],['ability',8]]){const b=battle('forest'),[u]=pokemon(b);b.field.setTerrain('grassyterrain',u,source==='move'?move(b,'grassyterrain'):b.dex.abilities.get('grassysurge'));assert.equal(b.rejuvenation.overlay.duration,duration);b.destroy();}});
test('Conversion and Conversion 2 build and restore Glitch across turns',()=>{const b=battle('indoor',{moves:['conversion','conversion2','watergun']},{moves:['growl']}),[u]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert(b.log.some(s=>s.includes('Some rogue data remains...')));b.choose('p1','move 2');b.choose('p2','move 1');assert.equal(E.current(b).id,fid('glitch'));assert(b.log.some(s=>s.includes('TH~ R0GUE DAa/ta cor$upt?@####')));assert.equal(b.rejuvenation.duration,4);for(let i=0;i<4;i++)b.residualEvent('Residual');assert.equal(E.current(b).id,fid('indoor'));b.destroy();});
test('binding damage combines captured Band and current field increments',()=>{for(const [field,mid,item,divisor]of [['desert','sandtomb','',6],['desert','sandtomb','Binding Band',4],['flower_garden_5','infestation','',3],['flower_garden_5','infestation','Binding Band',2],['water_surface','whirlpool','',6],['dragons_den','magmastorm','Binding Band',4]]){const b=battle(field,{item}),[u,t]=pokemon(b);t.addVolatile('partiallytrapped',u,move(b,mid));u.item='';const hp=t.hp;b.residualEvent('Residual');assert.equal(t.hp,hp-Math.floor(t.maxhp/divisor),field);b.destroy();}});
test('binding reads transformed fields and source stat loss guards',()=>{const b=battle('indoor'),[u,t]=pokemon(b);t.addVolatile('partiallytrapped',u,move(b,'sandtomb'));E.change(b,fid('desert'));const hp=t.hp;b.residualEvent('Residual');assert.equal(t.hp,hp-Math.floor(t.maxhp/6));E.change(b,fid('beach'));b.residualEvent('Residual');assert.equal(t.boosts.accuracy,-1);b.destroy();const a=battle('swamp',{}, {species:'Zapdos',ability:'Magic Guard'}),[v,w]=pokemon(a);const boosts={...w.boosts};w.addVolatile('partiallytrapped',v,move(a,'infestation'));a.residualEvent('Residual');assert.equal(w.hp,w.maxhp);assert.deepEqual(w.boosts,boosts);a.destroy();});
test('Swamp traps choose one source Omni stat and Underwater doubles Octolock',()=>{const b=battle('swamp'),[u,t]=pokemon(b);const sum=Object.values(t.boosts).reduce((n,x)=>n+x,0);t.addVolatile('partiallytrapped',u,move(b,'snaptrap'));b.residualEvent('Residual');assert.equal(Object.values(t.boosts).reduce((n,x)=>n+x,0),sum-3);b.destroy();const a=battle('underwater'),[v,w]=pokemon(a);w.addVolatile('octolock',v,move(a,'octolock'));a.residualEvent('Residual');assert.equal(w.boosts.def,-2);assert.equal(w.boosts.spd,-2);a.destroy();});
test('new metadata rejects malformed fields without altering loaded catalog',()=>{for(const change of [f=>f.grounding.airborneAbilities=['bad-id'],f=>f.terrainPolicy={moveDurations:{'rejuvenation:no_such_field':5}},f=>f.trapping.divisors=[1],f=>f.trapping.moveIncrements.sandtomb=5,f=>f.rules.push({event:'afterMove',condition:{always:true},actions:[{op:'pairField',memory:'pledge',duration:4,extendedBy:3,pairs:[{field:'rejuvenation:nope'}]}]})]){const c=JSON.parse(JSON.stringify(catalog));change(c.fields[fid('forest')]);assert.throws(()=>E.load(JSON.stringify(c)));}assert.equal(E.resolve({biome:'minecraft:forest'}),fid('forest'));});
test('Glitch Special pool compares boosts and held-item modified stats',()=>{const b=battle('glitch',{item:'Assault Vest'},{item:'Choice Specs'}),[u,t]=pokemon(b),m=move(b,'watergun');u.storedStats.spa=100;u.storedStats.spd=200;t.storedStats.spa=200;t.storedStats.spd=100;b.rejuvenationStatQuery={user:u,target:t,move:m};assert.equal(b.runEvent('ModifySpA',u,t,m,100),300);assert.equal(b.runEvent('ModifySpD',t,u,m,100),300);u.boosts.spa=6;assert.equal(b.runEvent('ModifySpA',u,t,m,100),400);m.willCrit=true;t.getMoveHitData(m).crit=true;t.boosts.spa=6;assert.equal(b.runEvent('ModifySpD',t,u,m,100),300);b.rejuvenationStatQuery=undefined;b.destroy();});
test('Glitch shared Special runs in actual damage and respects Unaware',()=>{const b=battle('glitch',{moves:['watergun']},{ability:'Unaware'}),[u,t]=pokemon(b),m=move(b,'watergun');m.willCrit=false;u.storedStats.spa=100;u.storedStats.spd=200;b.resetRNG([1,2,3,4]);const plain=b.actions.getDamage(u,t,m);u.boosts.spd=6;b.resetRNG([1,2,3,4]);assert.equal(b.actions.getDamage(u,t,m),plain);t.ability='synchronize';b.resetRNG([1,2,3,4]);assert(b.actions.getDamage(u,t,m)>plain);assert.equal(b.rejuvenationStatQuery,undefined);b.destroy();});
test('Glitch Genesect Drives absorb corresponding types and retain their item',()=>{for(const [item,mid,effect]of [['Shock Drive','thunderbolt','spe'],['Douse Drive','watergun','heal'],['Chill Drive','icebeam','heal'],['Burn Drive','flamethrower','fire']]){const b=battle('glitch',{moves:[mid]},{species:'Genesect',item,moves:['growl']}),[u,t]=pokemon(b);t.hp=Math.floor(t.maxhp/2);const before=t.hp;b.choose('p1','move 1');b.choose('p2','move 1');assert(t.item);if(effect==='spe'){assert.equal(t.boosts.spe,1);assert.equal(t.hp,before);}else if(effect==='heal')assert.equal(t.hp,before+Math.floor(t.maxhp/4));else{assert(t.volatiles.flashfire);assert.equal(t.hp,before);}b.destroy();}});
test('Glitch knockout clears recharge before the next action',()=>{const b=battle('glitch',{moves:['hyperbeam']},{moves:['growl']}),[u,t]=pokemon(b);t.hp=1;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.hp,0);assert(!u.volatiles.mustrecharge);b.destroy();});
test('Factory Motor Drive and Short Circuit cycle use native interception once',()=>{const a=battle('factory',{moves:['thunderbolt']},{ability:'Motor Drive',moves:['growl']}),[v,w]=pokemon(a);a.choose('p1','move 1');a.choose('p2','move 1');assert.equal(w.boosts.spe,2);assert.equal(w.hp,w.maxhp);a.destroy();for(const [ability,stat]of [['Lightning Rod','spa'],['Motor Drive','spe']]){const b=battle('short_circuit',{}, {ability}),[u,t]=pokemon(b),m=move(b,'thunderbolt'),a=t.getAbility();for(const expected of [1,3,3,4,6]){b.singleEvent('TryHit',a,t.abilityState,t,u,m);assert.equal(t.boosts[stat],expected);}assert.equal(b.rejuvenation.roll,0);b.destroy();}});
test('Short Circuit Volt Absorb scales healing and overlay maximizes the cycle',()=>{const b=battle('short_circuit',{}, {ability:'Volt Absorb'}),[u,t]=pokemon(b),m=move(b,'thunderbolt');for(const fraction of [.2,.375,.125,.3,.5]){t.hp=1;b.singleEvent('TryHit',t.getAbility(),t.abilityState,t,u,m);assert.equal(t.hp,1+Math.floor(t.maxhp*fraction));}E.change(b,fid('electric_terrain'),{duration:3});t.hp=1;b.singleEvent('TryHit',t.getAbility(),t.abilityState,t,u,m);assert.equal(t.hp,1+Math.floor(t.maxhp*.5));assert.equal(b.rejuvenation.roll,1);b.destroy();});
test('sunny Desert Water absorption and Magma Armor obey field conditions',()=>{const b=battle('desert',{moves:['watergun']},{species:'Bulbasaur',ability:'Chlorophyll',moves:['growl']}),[u,t]=pokemon(b);b.field.setWeather('sunnyday',u);t.hp=1;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.hp,1+Math.floor(t.maxhp/4));b.destroy();for(const ability of ['Synchronize','Mold Breaker']){const a=battle('dragons_den',{ability,moves:['flamethrower']},{ability:'Magma Armor',moves:['growl']}),[v,w]=pokemon(a);a.choose('p1','move 1');a.choose('p2','move 1');assert.equal(w.hp===w.maxhp,ability==='Synchronize');a.destroy();}});
test('Colosseum Wonder Guard prevents native poison residuals only on that field',()=>{const b=battle('colosseum',{}, {ability:'Wonder Guard'}),[u,t]=pokemon(b);t.setStatus('psn',t);b.residualEvent('Residual');assert.equal(t.hp,t.maxhp);E.change(b,fid('indoor'));b.residualEvent('Residual');assert(t.hp<t.maxhp);b.destroy();});
test('field immediate attacks skip charging without consuming Power Herb',()=>{for(const [field,mid]of [['desert','dig'],['water_surface','dive'],['cave','fly'],['dragons_den','bounce'],['sky','skyattack'],['grassy_terrain','razorwind'],['rainbow','solarbeam'],['frozen_dimension','freezeshock'],['frozen_dimension','iceburn'],['haunted','phantomforce'],['short_circuit','shadowforce']]){const b=battle(field,{item:'Power Herb',moves:[mid]}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.item,'powerherb',field+': '+mid);assert(!u.volatiles.twoturnmove,field+': '+mid);b.destroy();}});
test('ordinary charged attacks retain the native charging turn',()=>{const b=battle('indoor',{moves:['dig']}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert(u.volatiles.twoturnmove);assert.equal(t.hp,t.maxhp);b.destroy();});
test('Dark Crystal Solar attacks fail before consuming Power Herb',()=>{const b=battle('dark_crystal_cavern',{moves:['solarbeam'],item:'Power Herb'}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.item,'powerherb');assert.equal(t.hp,t.maxhp);assert(!u.volatiles.twoturnmove);assert(b.log.some(s=>s.includes('But it failed!')));b.destroy();});
test('Tailwind and Encore source clocks extend field effects',()=>{for(const [field,remaining]of [['sky',7],['mountain',5],['snowy_mountain',5],['volcanic_top',5]]){const b=battle(field,{moves:['tailwind']});b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(b.sides[0].sideConditions.tailwind.duration,remaining);b.destroy();}for(const [field,duration]of [['indoor',4],['big_top',7],['concert_4',7]]){const b=battle(field),[u,t]=pokemon(b);t.lastMove=move(b,'splash');assert(t.addVolatile('encore',u,move(b,'encore')));assert.equal(t.volatiles.encore.duration,duration);b.destroy();}});
test('Prankster status moves reach Dark foes only on source exception fields',()=>{for(const field of ['indoor','glitch','bewitched']){const b=battle(field,{ability:'Prankster',moves:['growl']},{species:'Umbreon'}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.boosts.atk,field==='indoor'?0:-1);b.destroy();}});
test('Starlight Meteor Assault has no recharge',()=>{const b=battle('starlight',{moves:['meteorassault']}),[u]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert(!u.volatiles.mustrecharge);b.destroy();});
test('New World Heart Swap shares capped HP after swapping stat stages',()=>{const b=battle('new_world',{moves:['heartswap']},{moves:['splash']}),[u,t]=pokemon(b);u.hp=10;t.hp=100;u.boosts.atk=2;t.boosts.def=3;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.hp,55);assert.equal(t.hp,55);assert.equal(u.boosts.def,3);assert.equal(t.boosts.atk,2);assert(b.log.some(s=>s.includes('shared their pain')));b.destroy();});
test('Psych Up cures Beach status and adds Psychic field Special Attack',()=>{const a=battle('beach',{moves:['psychup']}),[u,t]=pokemon(a);u.setStatus('par',u);a.choose('p1','move 1');a.choose('p2','move 1');assert.equal(u.status,'');a.destroy();const b=battle('psychic_terrain',{moves:['psychup']}),[v,w]=pokemon(b);w.boosts.spa=1;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(v.boosts.spa,3);b.destroy();});
test('field Weather Ball power and Strong Winds type use current weather',()=>{const a=battle('rainbow'),[u,t]=pokemon(a),m=move(a,'weatherball');a.runEvent('ModifyMove',u,t,m,m);assert.equal(m.basePower,100);a.destroy();const b=battle('sky'),[v,w]=pokemon(b);b.field.setWeather('deltastream',v);const n=move(b,'weatherball');b.runEvent('ModifyMove',v,w,n,n);assert.equal(n.basePower,100);assert.equal(n.type,'Flying');b.destroy();});
test('Haunted Ghost Curse pays quarter HP and leaves native curse active',()=>{const b=battle('haunted',{species:'Gengar',moves:['curse']},{moves:['splash']}),[u,t]=pokemon(b),before=u.hp;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.hp,before-Math.floor(u.maxhp/4));assert(t.volatiles.curse);b.destroy();const a=battle('haunted',{moves:['curse']}),[v]=pokemon(a);a.choose('p1','move 1');a.choose('p2','move 1');assert.equal(v.hp,v.maxhp);assert.equal(v.boosts.atk,1);a.destroy();});
test('Haunted Spite deducts six PP and clamps at remaining PP',()=>{const b=battle('haunted',{moves:['spite']}),[u,t]=pokemon(b);t.lastMove=move(b,'splash');t.storedStats.spe=1;t.moveSlots[0].pp=4;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.moveSlots[0].pp,0);assert(b.log.some(s=>s.includes('lost 4 PP')));b.destroy();});
test('Colosseum Roar raises user Attack and leaves the target in place',()=>{const b=battle('colosseum',{moves:['roar']}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.boosts.atk,2);assert.equal(b.sides[1].active[0],t);assert(b.log.some(s=>s.includes('stands their ground')));b.destroy();});
test('Nightmare permits awake Infernal targets and keeps the condition on cure',()=>{const b=battle('infernal',{moves:['nightmare']},{species:'Arcanine'}),[u,t]=pokemon(b);const before=t.hp;b.choose('p1','move 1');b.choose('p2','move 1');assert(t.volatiles.nightmare);assert.equal(t.hp,before-Math.floor(t.maxhp/4));t.setStatus('slp',t);t.cureStatus();assert(t.volatiles.nightmare);b.destroy();});
test('Nightmare Haunted residual increases and Rainbow suppresses then restores',()=>{const b=battle('haunted'),[u,t]=pokemon(b);t.setStatus('slp',t);assert(t.addVolatile('nightmare',u,move(b,'nightmare')));const before=t.hp;b.residualEvent('Residual');/* the nightmare and, separately, the spirits troubling a sleeper (Battle.rb:6547,6566) */assert.equal(t.hp,before-Math.floor(t.maxhp/3)-Math.floor(t.maxhp/16));E.change(b,fid('rainbow'));const next=t.hp;b.residualEvent('Residual');/* no nightmare damage; Rainbow's peaceful sleep heals instead (6578) */assert.equal(t.hp,next+Math.floor(t.maxhp/16));assert(t.volatiles.nightmare);E.change(b,fid('indoor'));t.cureStatus();assert(!t.volatiles.nightmare);b.destroy();});
test('overlay entry ability boosts apply to current and newly entering battlers',()=>{const b=battle('forest',{ability:'Forewarn'}),[u,t]=pokemon(b);E.change(b,fid('psychic_terrain'),{duration:3});assert.equal(u.boosts.spa,1);assert.equal(t.boosts.spa,0);b.runEvent('SwitchIn',u);assert.equal(u.boosts.spa,2);b.destroy();const a=battle('forest',{ability:'Water Compaction'}),[v]=pokemon(a);E.change(a,fid('misty_terrain'),{duration:3});assert.equal(v.boosts.def,2);a.destroy();});
test('hard field entry removes only source-incompatible overlays',()=>{for(const dest of ['new_world','underwater','corrosive_mist','misty_terrain']){const b=battle('forest');E.change(b,fid('misty_terrain'),{duration:3});assert(b.rejuvenation.overlay);E.change(b,fid(dest));assert.equal(b.rejuvenation.overlay,null,dest);b.destroy();}const b=battle('forest');E.change(b,fid('misty_terrain'),{duration:3});E.change(b,fid('rocky'));assert(b.rejuvenation.overlay);b.destroy();});
test('terrain cannot restart its current hard field or duplicate overlay',()=>{const b=battle('electric_terrain'),[u]=pokemon(b);assert.equal(b.field.setTerrain('electricterrain',u,move(b,'electricterrain')),false);E.change(b,fid('forest'));assert(b.field.setTerrain('electricterrain',u,move(b,'electricterrain')));assert.equal(b.field.setTerrain('electricterrain',u,move(b,'electricterrain')),false);b.destroy();});
test('overlay and weather-bound hard field clocks count down independently',()=>{const b=battle('forest'),[u]=pokemon(b);E.change(b,fid('rainbow'),{duration:5,force:true});b.field.setWeather('sunnyday',u);E.runActions([{op:'bindFieldClock',durationCondition:{weather:['sunnyday']},permanentCondition:{not:{field:fid('rainbow')}}}],{b});E.change(b,fid('grassy_terrain'),{duration:2});b.residualEvent('Residual');assert.equal(b.rejuvenation.overlay.duration,1);assert.equal(b.rejuvenation.duration,4);b.residualEvent('Residual');assert.equal(b.rejuvenation.overlay,null);assert.equal(b.rejuvenation.duration,3);assert.equal(E.current(b).id,fid('rainbow'));b.destroy();});
test('temporary expiry uses source-specific restored field message',()=>{const b=battle('new_world');E.change(b,fid('glitch'),{duration:1,force:true});b.residualEvent('Residual');assert.equal(E.current(b).id,fid('new_world'));assert(b.log.some(s=>s.includes('The world broke apart again!')));b.destroy();});
test('Mist creates a three-turn overlay or six with Amplifield Rock',()=>{for(const [item,duration]of [['',2],['Amplifield Rock',5],['Everstone',null]]){const b=battle('forest',{item,moves:['mist']}),[u]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert(u.side.sideConditions.mist);assert.equal(b.rejuvenation.overlay?.duration ?? null,duration);if(duration!==null)assert(b.log.some(s=>s.includes('Mist swirled around')));b.destroy();}const a=battle('underwater',{moves:['mist']});a.choose('p1','move 1');a.choose('p2','move 1');assert.equal(a.rejuvenation.overlay,null);a.destroy();});
test('Casual and Field Frenzy alter only source field multipliers',()=>{for(const [difficultyMode,fieldFrenzy,online,expected]of [[0,false,false,150],[1,false,false,125],[0,true,false,200],[1,true,false,150],[2,true,true,150]]){const b=battle('forest'),[u,t]=pokemon(b),m=move(b,'energyball');b.rejuvenation.mode={difficultyMode,fieldFrenzy,online};assert.equal(b.runEvent('BasePower',u,t,m,100),expected);b.destroy();}});
test('difficulty scaling includes reductions and preserves forbidden moves',()=>{for(const [difficultyMode,fieldFrenzy,expected]of [[0,false,50],[1,false,75],[0,true,25],[1,true,50]]){const b=battle('desert'),[u,t]=pokemon(b),m=move(b,'watergun');b.rejuvenation.mode={difficultyMode,fieldFrenzy,online:false};assert.equal(b.runEvent('BasePower',u,t,m,100),expected);b.destroy();}const b=battle('underwater',{moves:['flamethrower']}),[u,t]=pokemon(b);b.rejuvenation.mode={difficultyMode:1,fieldFrenzy:false,online:false};b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.hp,t.maxhp);b.destroy();});
test('per-battle options arrive through stream initialization and remain isolated',()=>{const s=new BattleStream();s._writeLine('start',JSON.stringify({formatid:'gen9customgame',rejuvenationField:fid('forest'),rejuvenationFieldOptions:{difficultyMode:1,fieldFrenzy:false}}));assert.equal(s.battle.rejuvenation.mode.difficultyMode,1);const b=battle('forest');assert.equal(b.rejuvenation.mode.difficultyMode,0);s.battle.destroy();b.destroy();const invalid=new Battle({formatid:'gen9customgame'});assert.throws(()=>E.attach(invalid,fid('forest'),{difficultyMode:99}));assert.equal(invalid.rejuvenation,undefined);invalid.destroy();});
test('flag flavor takes precedence over type flavor and appears once',()=>{const b=battle('fairytale'),[u,t]=pokemon(b),m=move(b,'behemothblade');m.flags.slicing=1;b.activeMove=m;b.runEvent('BasePower',u,t,m,100);b.runEvent('BasePower',u,t,m,100);assert.equal(b.log.filter(s=>s.includes('The blade cuts true!')).length,1);assert(!b.log.some(s=>s.includes('For justice!')));b.destroy();});
test('weather-suppressed Starlight power has no inactive flavor',()=>{const b=battle('starlight'),[u,t]=pokemon(b),m=move(b,'psychic');b.field.setWeather('raindance',u);b.activeMove=m;assert.equal(b.runEvent('BasePower',u,t,m,100),100);assert(!b.log.some(s=>s.includes('The astral energy boosted the attack!')));b.destroy();});
test('overlay flavor is selected only when the hard field lacks a type boost',()=>{const b=battle('indoor'),[u,t]=pokemon(b);E.change(b,fid('grassy_terrain'),{duration:3});let m=move(b,'energyball');b.activeMove=m;b.runEvent('BasePower',u,t,m,100);assert(b.log.some(s=>s.includes('The Grassy Terrain strengthened the attack!')));E.change(b,fid('forest'));const before=b.log.length;m=move(b,'energyball');b.activeMove=m;b.runEvent('BasePower',u,t,m,100);assert(!b.log.slice(before).some(s=>s.includes('The Grassy Terrain strengthened the attack!')));b.destroy();});
test('overlay move flavor is dispatched during actual field calculation',()=>{const b=battle('indoor'),[u,t]=pokemon(b);E.change(b,fid('grassy_terrain'),{duration:3});const m=move(b,'gust');b.activeMove=m;b.runEvent('BasePower',u,t,m,100);assert(b.log.some(s=>s.includes('The wind picked up strength from the field!')));b.destroy();});
test('contextual doubled attacks replace native conditions without stacking',()=>{for(const [field,mid,bp,callback,status]of [['corrosive','venoshock',130,'onBasePower','psn'],['deux_finalis','brine',130,'onBasePower',''],['deux_finalis','smellingsalts',140,'basePowerCallback','par'],['infernal','hex',130,'basePowerCallback','brn']]){const b=battle(field),[u,t]=pokemon(b),m=move(b,mid);b.runEvent('ModifyMove',u,t,m,m);assert.equal(m.basePower,bp);assert.equal(m[callback],undefined);t.setStatus(status,t);const n=move(b,mid);b.runEvent('ModifyMove',u,t,n,n);assert.equal(n.basePower,bp);assert.equal(n[callback],undefined);b.destroy();}});
test('Venom Drench affects healthy targets on polluted fields but remains native elsewhere',()=>{for(const field of ['corrosive','corrosive_mist','wasteland','murkwater_surface','indoor']){const b=battle(field,{moves:['venomdrench']}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.boosts.atk,field==='indoor'?0:-1,field);assert.equal(t.boosts.spa,field==='indoor'?0:-1,field);assert.equal(t.boosts.spe,field==='indoor'?0:-1,field);b.destroy();}});
test('Colosseum First Impression ignores Protect only on that field',()=>{for(const field of ['colosseum','indoor']){const b=battle(field,{moves:['firstimpression']},{moves:['protect']}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.hp<t.maxhp,field==='colosseum');b.destroy();}});
test('Colosseum damaging phazing keeps damage and removes forced switching',()=>{for(const mid of ['dragontail','circlethrow']){const b=battle('colosseum'),[u,t]=pokemon(b),m=move(b,mid);b.runEvent('ModifyMove',u,t,m,m);assert.equal(m.forceSwitch,false);assert(m.basePower>0);b.destroy();}});
test('Deux Finalis Clanging Scales leaves Defense unchanged',()=>{const b=battle('deux_finalis',{moves:['clangingscales']}),[u]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.boosts.def,0);b.destroy();const a=battle('indoor',{moves:['clangingscales']}),[v]=pokemon(a);a.choose('p1','move 1');a.choose('p2','move 1');assert.equal(v.boosts.def,-1);a.destroy();});
test('Deux Finalis Lucky Chant adds five-turn side Mist without creating terrain',()=>{const b=battle('deux_finalis',{moves:['luckychant']}),[u]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.side.sideConditions.luckychant.duration,4);assert.equal(u.side.sideConditions.mist.duration,4);assert.equal(b.rejuvenation.overlay,null);assert(b.log.some(s=>s.includes("Lucky Chant's team became shrouded in mist!")));b.destroy();});
test('invalid side condition action rejects a reload',()=>{const c=JSON.parse(JSON.stringify(catalog));c.fields[fid('forest')].rules.push({event:'residual',condition:{always:true},actions:[{op:'sideCondition',id:'nonsense'}]});assert.throws(()=>E.load(JSON.stringify(c)));});
test('room and Gravity clocks use source fields and working Amplifield Rock',()=>{for(const [field,item,mid,duration]of [['chess_board','','trickroom',7],['new_world','','wonderroom',7],['starlight','','magicroom',7],['psychic_terrain','','gravity',7],['indoor','Amplifield Rock','trickroom',7],['indoor','Amplifield Rock','magicroom',7],['indoor','','wonderroom',4]]){const b=battle(field,{moves:[mid],item}),[u]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(b.field.pseudoWeather[mid].duration,duration,field+' '+mid);assert.equal(b.rejuvenation.clockOverride,undefined);b.destroy();}const b=battle('indoor',{moves:['magicroom'],item:'Amplifield Rock',ability:'Klutz'});b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(b.field.pseudoWeather.magicroom.duration,4);b.destroy();});
test('Dimensional random clock takes precedence over duration-extending items',()=>{for(const mid of ['gravity','trickroom','wonderroom','magicroom']){const b=battle('dimensional',{item:'Amplifield Rock'}),[u]=pokemon(b);const old=b.random.bind(b),calls=[];b.random=function(a,c){if(a===3&&c===9){calls.push([a,c]);return 3;}return old(a,c);};assert(b.field.addPseudoWeather(mid,u,move(b,mid)));assert.equal(b.field.pseudoWeather[mid].duration,3);assert.equal(calls.length,1);b.destroy();}});
test('Magnet Rise clocks respect electric fields and overlays',()=>{for(const [field,overlay]of [['factory',false],['short_circuit',false],['electric_terrain',false],['forest',true],['indoor',false]]){const b=battle(field,{moves:['magnetrise']}),[u]=pokemon(b);if(overlay)E.change(b,fid('electric_terrain'),{duration:3});b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.volatiles.magnetrise.duration,field==='indoor'?4:7);b.destroy();}});
test('Psychic terrain Telekinesis lowers both defensive stages',()=>{const b=battle('psychic_terrain',{moves:['telekinesis']}),[u,t]=pokemon(b);b.choose('p1','move 1');b.choose('p2','move 1');assert(t.volatiles.telekinesis);assert.equal(t.boosts.def,-2);assert.equal(t.boosts.spd,-2);b.destroy();});
test('malformed duration choices reject catalog reload',()=>{const c=JSON.parse(JSON.stringify(catalog));c.fields[fid('forest')].conditionDurations.magicroom.choices=[{condition:{always:true},randomRange:{minimum:8,maximum:3}}];assert.throws(()=>E.load(JSON.stringify(c)));});
test('Sky Flying Press preserves the shipped first-type double-check and resistance exception',()=>{for(const [types,sky,ordinary]of [[['Grass','Rock'],3,1],[['Rock','Grass'],1,1],[['Electric'],0,-1]]){for(const [field,expected]of [['sky',sky],['indoor',ordinary]]){const b=battle(field),[u,t]=pokemon(b),m=move(b,'flyingpress');t.setType(types);b.runEvent('ModifyMove',u,t,m,m);assert.equal(t.runEffectiveness(m),expected,field+' '+types);b.destroy();}}});
test('capture metadata covers every original field branch and rejects bad factors',()=>{for(const field of ['water_surface','underwater'])assert.equal(fields[fid(field)].captureModifiers['cobblemon:dive_ball'],3.5);for(const field of ['dark_crystal_cavern','short_circuit','underwater','cave','crystal_cavern','dragons_den','starlight','new_world','inverse'])assert.equal(fields[fid(field)].captureModifiers['cobblemon:dusk_ball'],3.5);assert.equal(fields[fid('forest')].captureModifiers,undefined);const c=JSON.parse(JSON.stringify(catalog));c.fields[fid('forest')].captureModifiers={'cobblemon:dive_ball':-1};assert.throws(()=>E.load(JSON.stringify(c)));});
test('Stance Change modifies stages on actual form changes in Chess and Fairy Tale',()=>{for(const field of ['chess_board','fairytale','indoor']){const b=battle(field,{species:'Aegislash',ability:'Stance Change',moves:['shadowball','kingsshield']},{species:'Blissey'}),[u,t]=pokemon(b),atk=u.boosts.atk,def=u.boosts.def;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.species.id,'aegislashblade');assert.equal(u.boosts.atk,atk+(field==='indoor'?0:1));assert.equal(u.boosts.def,def-(field==='indoor'?0:1));const currentAtk=u.boosts.atk;b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(u.boosts.atk,currentAtk);b.choose('p1','move 2');b.choose('p2','move 1');assert.equal(u.species.id,'aegislash');assert.equal(u.boosts.atk,atk);assert.equal(u.boosts.def,def);b.destroy();}});
test('type-forbidden moves dispatch their original type failure message',()=>{const b=battle('underwater',{moves:['flamethrower']}),[u,t]=pokemon(b),row=fields[fid('underwater')].types.find(r=>r.match.moveType==='Fire'&&r.multiplier===0);b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(t.hp,t.maxhp);assert(row.message);assert(b.log.some(s=>s.includes(row.message.replaceAll('|',''))));b.destroy();});
test('weather creation rejects before native start while field entry clears existing weather',()=>{for(const [field,weather,text]of [['new_world','raindance','The weather drifted off into space...'],['underwater','sunnyday',"You're too deep to notice the weather!"],['volcanic','hail','The hail melted away.'],['infernal','raindance','The rain evaporated.']]){const b=battle(field),[u]=pokemon(b);const before=b.log.length;b.field.setWeather(weather,u);assert.equal(b.field.weather,'');assert(b.log.slice(before).some(s=>s.includes(text)));assert(!b.log.slice(before).some(s=>s.startsWith('|-weather|')&&!s.includes('|none')));b.destroy();}const b=battle('forest'),[u]=pokemon(b);b.field.setWeather('raindance',u);E.change(b,fid('new_world'));assert.equal(b.field.weather,'');assert(b.log.some(s=>s.includes('The weather disappeared into space!')));b.destroy();});
test('Frozen Dimension converts Snow before native weather initialization',()=>{const b=battle('frozen_dimension'),[u]=pokemon(b);const before=b.log.length;b.field.setWeather('snow',u,move(b,'snowscape'));assert.equal(b.field.weather,'hail');assert.equal(b.field.weatherState.duration,8);assert(!b.log.slice(before).some(s=>s.includes('|Snow')));b.destroy();});
test('field weather duration applies to moves and weather abilities without double extending rocks',()=>{for(const [field,mid,item,duration]of [['desert','sunnyday','',7],['sky','raindance','Damp Rock',7],['beach','sandstorm','',7],['icy','snowscape','',7],['indoor','sunnyday','Heat Rock',7],['indoor','raindance','',4]]){const b=battle(field,{moves:[mid],item});b.choose('p1','move 1');b.choose('p2','move 1');assert.equal(b.field.weatherState.duration,duration,field+' '+mid);b.destroy();}for(const [field,ability]of [['desert','Drought'],['sky','Drizzle'],['beach','Sand Stream'],['icy','Snow Warning']]){const b=battle(field,{ability});assert.equal(b.field.weatherState.duration,8,ability);b.destroy();}});
test('Sky Cloud Nine prevents weather creation rather than merely suppressing it',()=>{const b=battle('sky',{}, {ability:'Cloud Nine'}),[u]=pokemon(b);assert.equal(b.field.setWeather('raindance',u),null);assert.equal(b.field.weather,'');assert(b.log.some(s=>s.includes('But it failed!')));b.destroy();});
test('Mimicry preserves added types and avoids repeated unchanged flavor',()=>{const b=battle('forest',{ability:'Mimicry'}),[u]=pokemon(b);u.addType('Ghost');E.change(b,fid('desert'));assert.deepEqual(u.getTypes(),['Ground','Ghost']);assert.equal(u.addedType,'Ghost');E.change(b,fid('indoor'));assert.deepEqual(u.getTypes(),['Psychic','Ghost']);const before=b.log.length;b.runEvent('SwitchIn',u);assert(!b.log.slice(before).some(s=>s.includes('returned to its original type!')));b.destroy();});
